interface DeleteUnusedTagsButtonProps {
  workspaceId: string;
  isReadOnly: boolean;
}

export const DeleteUnusedTagsButton = ({ workspaceId, isReadOnly }: DeleteUnusedTagsButtonProps) => {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const deleteUnusedTagsMutation = useDeleteUnusedTags(workspaceId);

  const handleDelete = async () => {
    try {
      const result = await deleteUnusedTagsMutation.mutateAsync();
      toast.success(t(\"workspace.tags.tags_deleted\", { count: result.count }));
    } catch {
      toast.error(t(\"common.something_went_wrong_please_try_again\"));
    }
    setOpen(false);
  };

  if (isReadOnly) return null;

  return (
    <>
      <Button
        variant=\"destructive\"
        size=\"sm\"
        loading={deleteUnusedTagsMutation.isPending}
        onClick={() => setOpen(true)}>
        {t(\"workspace.tags.delete_unused_tags\")}
      </Button>
      <DeleteDialog
        open={open}
        setOpen={setOpen}
        deleteWhat={t(\"workspace.tags.delete_unused_tags\")}
        text={t(\"workspace.tags.delete_unused_tags_confirmation\")}
        onDelete={handleDelete}
        isDeleting={deleteUnusedTagsMutation.isPending}
      />
    </>
  );
};
